// Parar ihop HTTP-svaren med orgnr från föregående nod (samma ordning, 1:1).
// desired   = önskat läge, alla aktiva roller enligt BRREG just nu.
// processed = orgnr som gick att läsa av (200 eller 404). Bara dessa får stängas.

const ROLE_MAP = {
  LEDE: 'styreleder',
  NEST: 'nestleder',
  MEDL: 'styremedlem',
  VARA: 'varamedlem',
  OBS: 'observator',
  DAGL: 'daglig_leder',
  REVI: 'revisor',
  REGN: 'regnskapsforer',
  INNH: 'innehaver',
  KONT: 'kontaktperson',
  BEST: 'bestyrende_reder',
  KOMP: 'komplementar',
  FFOR: 'forretningsforer'
};

// Normalt kommer orgnr från "Changed orgnrs". Vid manuell backfill kopplas
// "Backfill segment (manuell)" in i stället, därav fallbacken.
let source;
try {
  source = $('Changed orgnrs').all();
} catch (err) {
  source = $('Backfill segment (manuell)').all();
}

const responses = $input.all();

if (source.length === 0 || responses.length === 0) {
  // Inga orgnr att behandla. Tomt svar stoppar diffen och lämnar markören orörd.
  return [];
}

const desired = [];
const processed = [];
let noRoles = 0;
let serverErrors = 0;

for (let i = 0; i < responses.length; i++) {
  const orgnr = String(source[i]?.json?.orgnr ?? '').trim();
  if (!orgnr) continue;

  const res = responses[i]?.json ?? {};
  const status = Number(res.statusCode);

  if (status >= 500) {
    // Serverfel hos BRREG. Orgnret utesluts ur processed så att inga roller stängs.
    serverErrors++;
    continue;
  }

  if (status === 404) {
    // 404 = inga roller registrerade. Räknas som behandlat, alla öppna roller stängs.
    noRoles++;
    processed.push(orgnr);
    continue;
  }

  if (status !== 200) continue;

  processed.push(orgnr);

  const rollegrupper = res.body?.rollegrupper ?? [];

  for (const gruppe of rollegrupper) {
    const roller = gruppe?.roller ?? [];

    for (const entry of roller) {
      if (entry?.fratraadt === true) continue;

      const kode = entry?.type?.kode ?? null;
      const roleType = ROLE_MAP[kode] ?? (kode ? String(kode).toLowerCase() : null);
      if (!roleType) continue;

      let personName = null;
      let birthDate = null;
      let holderOrgnr = null;

      if (entry.person) {
        // navn är ett strukturerat objekt i det här API:et, inte en platt sträng.
        const navn = entry.person.navn ?? {};
        personName = [navn.fornavn, navn.mellomnavn, navn.etternavn].filter(Boolean).join(' ').trim() || null;
        birthDate = entry.person.fodselsdato ?? null;
      } else if (entry.enhet) {
        holderOrgnr = entry.enhet.organisasjonsnummer != null ? String(entry.enhet.organisasjonsnummer) : null;
      }

      if (!personName && !holderOrgnr) continue;

      desired.push({
        company_orgnr: orgnr,
        role_type: roleType,
        person_name: personName,
        birth_date: birthDate,
        holder_orgnr: holderOrgnr
      });
    }
  }
}

if (serverErrors > 0 && serverErrors === responses.length) {
  throw new Error('Samtliga ' + serverErrors + ' anrop mot BRREG gav 5xx. Avbryter så att inga roller stängs felaktigt.');
}

// Ny markör: högsta event_id i batchen plus ett.
let maxEventId = 0;
for (const item of source) {
  const n = Number(item?.json?.max_event_id);
  if (Number.isFinite(n) && n > maxEventId) maxEventId = n;
}

let nextCursor;
if (maxEventId > 0) {
  nextCursor = String(maxEventId + 1);
} else {
  // Backfill-noden levererar max_event_id = 0. Då skrivs samma markör tillbaka.
  let current = '';
  try {
    current = String($('Get cursor').first().json.value ?? '');
  } catch (err) {
    current = '';
  }
  nextCursor = current === '' ? '0' : current;
}

return [{
  json: {
    desired: JSON.stringify(desired),
    processed: JSON.stringify(processed),
    nextCursor: nextCursor,
    orgnr_in: responses.length,
    orgnr_processed: processed.length,
    roles_desired: desired.length,
    no_roles_404: noRoles,
    server_errors_5xx: serverErrors
  }
}];
